return items.map((item, index) => {
  const j = item.json || {};
  const ahora = new Date();
  const ts = Date.now();

  const headers = Array.isArray(j.payload?.headers)
    ? j.payload.headers
    : [];

  const getHeader = (name) => {
    const h = headers.find(
      x => String(x.name || '').toLowerCase() === name.toLowerCase()
    );
    return h?.value || '';
  };

  const fromRaw =
    j.from ||
    j.From ||
    getHeader('From') ||
    '';

  const toRaw =
    j.to ||
    j.To ||
    getHeader('To') ||
    '';

  const extraerEmail = (valor) => {
    const texto = String(valor || '').trim();
    const angle = texto.match(/<([^>]+)>/);
    if (angle) return angle[1].trim().toLowerCase();

    const email = texto.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
    return email ? email[0].toLowerCase() : texto.toLowerCase();
  };

  const remitente = extraerEmail(fromRaw);
  const destinatario = extraerEmail(toRaw);

  const asunto =
    j.subject ||
    j.Subject ||
    getHeader('Subject') ||
    '(Sin asunto)';

  let cuerpo =
    j.textPlain ||
    j.text ||
    j.snippet ||
    j.body ||
    '';

  if (!cuerpo && Array.isArray(j.payload?.parts)) {
    const plain = j.payload.parts.find(p => p.mimeType === 'text/plain');
    if (plain?.body?.data) {
      try {
        cuerpo = Buffer
          .from(plain.body.data.replace(/-/g, '+').replace(/_/g, '/'), 'base64')
          .toString('utf8');
      } catch (e) {
        cuerpo = '';
      }
    }
  }

  if (!cuerpo && j.payload?.mimeType === 'text/plain' && j.payload?.body?.data) {
    try {
      cuerpo = Buffer
        .from(j.payload.body.data.replace(/-/g, '+').replace(/_/g, '/'), 'base64')
        .toString('utf8');
    } catch (e) {
      cuerpo = '';
    }
  }

  const labels = Array.isArray(j.labelIds)
    ? j.labelIds
    : Array.isArray(j.labels)
      ? j.labels.map(x => typeof x === 'string' ? x : (x.id || x.name))
      : [];

  const origen_carpeta = labels.includes('SPAM') ? 'spam' : 'bandeja';

  // Ground truth opcional para pruebas controladas:
  // ceficperu0+phishing@gmail.com
  // ceficperu0+spam@gmail.com
  // ceficperu0+legitimo@gmail.com
  const destinoLower = String(toRaw || '').toLowerCase();
  let categoria_real = 'pendiente_validacion';

  if (destinoLower.includes('+phishing@')) {
    categoria_real = 'phishing';
  } else if (destinoLower.includes('+spam@')) {
    categoria_real = 'spam';
  } else if (destinoLower.includes('+legitimo@')) {
    categoria_real = 'legitimo';
  }

  const fechaCorreo = j.internalDate
    ? new Date(Number(j.internalDate))
    : ahora;

  return {
    json: {
      id_gmail: j.id || null,
      thread_id_gmail: j.threadId || null,

      id_ejecucion:
        'CLAS-SEG-' +
        ts +
        '-' +
        index +
        '-' +
        Math.random().toString(36).slice(2, 7),

      id_incidente:
        'INC-CLAS-' +
        ts +
        '-' +
        index +
        '-' +
        Math.random().toString(36).slice(2, 7),

      flujo: '05',
      proceso: 'clasificador_correos',
      escenario: 'con_seguridad',

      origen_carpeta,
      remitente,
      destinatario,
      asunto,
      cuerpo,
      categoria_real,

      hora_ingreso: fechaCorreo
        .toISOString()
        .slice(0, 19)
        .replace('T', ' ')
    }
  };
});
